 const addFor=(classId,subclass,names,level=3)=>{if(owns013(c,classId,subclass,level))for(const name of names)add(classId,subclass,name);};
 addFor('bardo','Colégio do Glamour',['Enfeitiçar Pessoa','Reflexos']);addFor('bardo','Colégio do Glamour',['Comando'],6);
 addFor('druida','Círculo das Estrelas',['Orientação','Raio Guia']);
