 if(!spec.healing&&level013(c,'clerigo')>=7&&choice013(c,'blessedStrike')==='Conjuração Potente'&&sourceClassId==='clerigo'&&spell.level===0){add(mod013(c,'wis'));notes.push('Conjuração Potente de 2024: SAB já incluído; não some a característica antiga novamente.');}
