export function subclassWeaponMastery013(c,w){const key=Object.entries(state013(c).weaponLinks||{}).find(([,id])=>id===w.id)?.[0];return subclassWeaponPresets013(c).find(p=>p.id===key)?.mastery||'';}

function bladesongValid013(c){return owns013(c,'mago','Lâmina Cantante')&&state013(c).active.bladesong&&(c.armor==='none'||['acolchoada','couro','courobatido','batido'].includes(c.armor)||c.customArmors?.some(a=>'custom:'+a.id===c.armor&&a.category==='Leve'))&&!c.shield&&!c.weapons?.some(w=>w.two)&&!c.conditions?.some(x=>['Incapacitado','Inconsciente','Paralisado','Atordoado','Petrificado'].includes(x));}
export function onSubclassClassResource013(c,id){if(id==='rage'&&!c.raging&&owns013(c,'barbaro','Trilha da Árvore do Mundo'))c.tempHp=Math.max(c.tempHp||0,level013(c,'barbaro'));if(id==='cunning'&&owns013(c,'bruxo','Patrono Celestial',10))c.tempHp=Math.max(c.tempHp||0,Math.max(0,level013(c,'bruxo')+mod013(c,'cha')));}
export function subclassWeaponDamage013(c,weapon){return !weapon.ranged&&owns013(c,'mago','Lâmina Cantante',14)&&bladesongValid013(c)?Math.max(1,mod013(c,'int')):0;}
